import {requireVendorManager} from '@/lib/auth/vendor';import {fcfa,getVendorProducts,getVendorPromotions} from '@/services/vendor-dashboard';import {createPromotion} from '@/app/vendor/actions';import {ActionForm} from '@/components/vendor-forms';
export default async function PromotionsPage(){const context=await requireVendorManager();const[promotions,products]=await Promise.all([getVendorPromotions(context.restaurant!.id),getVendorProducts(context.restaurant!.id)]);return <><div className="vendor-page-head"><div><p className="section-kicker">Offres</p><h1>Promotions</h1><p>Créez une offre simple pour votre restaurant ou un produit.</p></div></div><div className="vendor-two-columns"><section className="vendor-card"><h2>Nouvelle promotion</h2><ActionForm action={createPromotion} submitLabel="Créer la promotion"><label className="field"><span>Nom</span><input name="name" required placeholder="Ex. Offre du week-end"/></label><div className="vendor-form-grid"><label className="field"><span>Type</span><select name="discount_type"><option value="percent">Pourcentage</option><option value="fixed">Montant fixe</option></select></label><label className="field"><span>Valeur</span><input name="value" type="number" min="0" required/></label><label className="field full"><span>Produit concerné <small>facultatif</small></span><select name="product_id"><option value="">Tout le restaurant</option>{products.filter(item=>!item.is_archived).map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="field"><span>Date de début</span><input name="starts_at" type="datetime-local"/></label><label className="field"><span>Date de fin</span><input name="ends_at" type="datetime-local"/></label></div><label className="availability-check"><input name="is_active" type="checkbox" defaultChecked/><span><strong>Promotion active</strong><small>Elle sera appliquée pendant les dates choisies.</small></span></label></ActionForm></section><section className="vendor-card"><h2>Promotions créées</h2>{promotions.length?<div className="promotion-list">{promotions.map(promotion=>{const product=promotion.product as unknown as {name?:string}|null;return <article key={promotion.id}><span><strong>{promotion.name}</strong><small>{product?.name??'Tout le restaurant'} · {promotion.discount_type==='percent'?`${promotion.value} %`:fcfa(promotion.value)}</small></span><span className={promotion.is_active?'vendor-badge success':'vendor-badge muted'}>{promotion.is_active?'Active':'Inactive'}</span></article>})}</div>:<div className="vendor-empty"><strong>Aucune promotion.</strong><p>Votre première offre apparaîtra ici.</p></div>}</section></div></>}
